import fs from 'fs';
import { SourceMapConsumer } from 'source-map';

async function resolve() {
  const rawSourceMap = fs.readFileSync('dist/assets/index-B2ZVSBhO.js.map', 'utf8');
  const consumer = await new SourceMapConsumer(rawSourceMap);
  
  const generatedCode = fs.readFileSync('dist/assets/index-B2ZVSBhO.js', 'utf8');
  const lines = generatedCode.split('\n');
  
  if (lines.length >= 8) {
     const line8 = lines[7]; // 0-indexed
     
     // Find the occurrences of "Cannot access 'o' before initialization" ? No, that's generated by the JS engine.
     // Let's print out some positions from line 8
     for(let col = 0; col < Math.min(line8.length, 1000); col += 100) {
         const pos = consumer.originalPositionFor({ line: 8, column: col });
         console.log(`Col ${col}:`, pos);
     }
  }
  
  consumer.destroy();
}

resolve();
